#!/usr/bin/env python3
"""Validation script for pipeline outputs (T14)."""

import json
import os
import sys

try:
    import pandas as pd
except ImportError:
    pd = None


def check_file_exists(filepath, check_name):
    """Check if a file exists."""
    exists = os.path.exists(filepath)
    size = os.path.getsize(filepath) if exists else 0
    passed = exists and size > 0
    message = (
        f"File '{filepath}' exists and is not empty ({size} bytes)"
        if passed
        else f"File '{filepath}' is missing or empty"
    )
    return {"check_name": check_name, "passed": passed, "message": message}


def check_csv_readable(filepath, check_name):
    """Check if a CSV file can be read and has data rows."""
    if not os.path.exists(filepath):
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"File '{filepath}' not found",
        }

    try:
        df = pd.read_csv(filepath)
        row_count = len(df)
        col_count = len(df.columns)
        passed = row_count > 0 and col_count > 0
        message = f"File '{filepath}' is readable with {row_count} rows and {col_count} columns"
        return {"check_name": check_name, "passed": passed, "message": message}
    except Exception as e:
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"Error reading '{filepath}': {str(e)}",
        }


def check_csv_has_columns(filepath, check_name, required_columns):
    """Check if a CSV file has the required columns."""
    if not os.path.exists(filepath):
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"File '{filepath}' not found",
        }

    try:
        df = pd.read_csv(filepath)
        missing = [col for col in required_columns if col not in df.columns]
        if missing:
            return {
                "check_name": check_name,
                "passed": False,
                "message": f"File '{filepath}' missing columns: {missing}",
            }
        return {
            "check_name": check_name,
            "passed": True,
            "message": f"File '{filepath}' contains all required columns: {required_columns}",
        }
    except Exception as e:
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"Error reading '{filepath}' for column check: {str(e)}",
        }


def check_csv_no_null_coords(filepath, check_name):
    """Check that coordinate columns have no null values (for spatial files)."""
    if not os.path.exists(filepath):
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"File '{filepath}' not found",
        }

    try:
        df = pd.read_csv(filepath)
        lat_nulls = df["latitude"].isna().sum() if "latitude" in df.columns else 0
        lon_nulls = df["longitude"].isna().sum() if "longitude" in df.columns else 0
        passed = lat_nulls == 0 and lon_nulls == 0
        message = f"File '{filepath}' has no null coordinates (lat_nulls={lat_nulls}, lon_nulls={lon_nulls})"
        return {"check_name": check_name, "passed": passed, "message": message}
    except Exception as e:
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"Error checking coordinates in '{filepath}': {str(e)}",
        }


def main():
    base_dir = os.getcwd()
    outputs_dir = os.path.join(base_dir, "outputs")

    # Define files and their expected columns
    files = {
        "t01_selected_indicators.csv": [
            "indicator_id",
            "indicator_name",
        ],
        "t05_clean_stops.csv": [
            "stop_id",
            "latitude",
            "longitude",
        ],
        "t08_pois_clean.csv": [
            "pois_id",
            "category",
            "latitude",
            "longitude",
        ],
        "t10_accessibility_scores.csv": [
            "location_id",
            "accessibility_score",
        ],
        "t13_city_clusters.csv": [
            "location_id",
            "cluster_id",
        ],
    }

    checks = []

    for filename, required_cols in files.items():
        filepath = os.path.join(outputs_dir, filename)
        prefix = filename.replace(".csv", "")

        # Check 1: File exists and is not empty
        checks.append(check_file_exists(filepath, f"{prefix}_file_exists"))

        # Check 2: CSV is readable and has data
        checks.append(check_csv_readable(filepath, f"{prefix}_has_data"))

        # Check 3: Required columns present
        checks.append(
            check_csv_has_columns(filepath, f"{prefix}_has_required_columns", required_cols)
        )

        # Check 4: Spatial files have valid coordinates
        if "latitude" in required_cols and "longitude" in required_cols:
            checks.append(
                check_csv_no_null_coords(filepath, f"{prefix}_no_null_coords")
            )

    # Write summary JSON
    summary_path = os.path.join(outputs_dir, "t14_validation_summary.json")
    os.makedirs(os.path.dirname(summary_path), exist_ok=True)

    with open(summary_path, "w") as f:
        json.dump(checks, f, indent=2)

    # Print summary to stdout
    passed = sum(1 for c in checks if c["passed"])
    total = len(checks)
    print(f"T14 Validation Summary: {passed}/{total} checks passed")

    for c in checks:
        status = "PASS" if c["passed"] else "FAIL"
        print(f"  [{status}] {c['check_name']}: {c['message']}")

    if passed < total:
        sys.exit(1)


if __name__ == "__main__":
    main()
